create table if not exists public.creator_memory_constellation_restriction_profiles (id uuid primary key default gen_random_uuid(), source_trust_node_id uuid not null, version text not null, profile jsonb not null, source_manifest_id uuid not null, state text not null, created_at timestamptz not null default now(), unique(source_trust_node_id, version));
create table if not exists public.creator_memory_constellation_protocol_profiles (id uuid primary key default gen_random_uuid(), profile_type text not null, version text not null, normative_schema jsonb not null, state text not null, effective_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), unique(profile_type, version));
create table if not exists public.creator_memory_constellation_funding_decisions (id uuid primary key default gen_random_uuid(), fund_ref uuid not null, recipient_trust_node_id uuid, purpose text not null, amount_minor bigint, currency text, conflicts jsonb not null default '[]'::jsonb, concentration_snapshot jsonb not null, state text not null, source_manifest_id uuid not null, created_at timestamptz not null default now());
create table if not exists public.creator_memory_constellation_remote_research (id uuid primary key default gen_random_uuid(), research_type text not null, protocol jsonb not null, legal_reviews jsonb not null default '[]'::jsonb, scientific_reviews jsonb not null default '[]'::jsonb, production_deployment_allowed boolean not null default false, state text not null, source_manifest_id uuid not null, created_at timestamptz not null default now());
